/**
 * The compile pipeline: Context + resolved targets → generated outputs.
 *
 *   .map ──loader──▶ Context ──adapter──▶ body ──banner──▶ CompiledOutput
 *
 * This module ties an adapter to its configured output path and prepends the
 * "generated — do not edit" banner in the comment style the adapter declares. Writing
 * to disk is the caller's job (the `sync` command), keeping the pipeline pure.
 */

import { createHash } from "node:crypto";
import type { Context } from "./context.ts";
import type { ResolvedCompilerConfig } from "./compiler-config.ts";
import type { AdapterRegistry, BannerStyle } from "./adapters/index.ts";

export interface CompiledOutput {
  readonly target: string;
  /** Output path relative to the project root, from the config. */
  readonly path: string;
  readonly content: string;
}

export interface CompileResult {
  readonly outputs: readonly CompiledOutput[];
  /** Target ids whose adapter could not be resolved. */
  readonly unknownTargets: readonly string[];
}

const BANNER_LINES = [
  "Generated by MAP. Do not edit directly.",
  "Edit the files inside .map/ and run `map sync` to regenerate.",
];

/** Marker that identifies a MAP-generated file, kept stable across versions. */
export const GENERATED_MARKER = "Generated by MAP.";
const HASH_PLACEHOLDER = "0".repeat(64);
const HASH_LINE = /map-sha256: ([0-9a-f]{64})/;

/**
 * Ownership of an existing output file:
 *   generated  produced by MAP and unchanged since (safe to regenerate);
 *   legacy     produced by an older MAP without a content hash (regenerated);
 *   modified   produced by MAP but edited by hand afterwards (conflict);
 *   user       not produced by MAP (never overwritten without --force).
 */
export type Ownership = "generated" | "legacy" | "modified" | "user";

export function ownershipOf(content: string): Ownership {
  const head = content.slice(0, 4096);
  if (!head.includes(GENERATED_MARKER)) return "user";
  const match = HASH_LINE.exec(head);
  if (match === null) return "legacy";
  return hashOf(content.replace(match[1]!, HASH_PLACEHOLDER)) === match[1] ? "generated" : "modified";
}

function hashOf(content: string): string {
  return createHash("sha256").update(content).digest("hex");
}

export function compile(
  context: Context,
  config: ResolvedCompilerConfig,
  registry: AdapterRegistry,
): CompileResult {
  const outputs: CompiledOutput[] = [];
  const unknownTargets: string[] = [];

  for (const target of config.targets) {
    const adapter = registry.get(target.adapter);
    if (adapter === undefined) {
      unknownTargets.push(target.id);
      continue;
    }
    const body = adapter.compile(context);
    outputs.push({
      target: target.id,
      path: target.output,
      content: withBanner(body, adapter.bannerStyle),
    });
  }

  return { outputs, unknownTargets };
}

/**
 * Prepend the banner. When the output opens with its own frontmatter block (Cursor's
 * MDC), the banner is inserted *after* that block so the frontmatter stays first.
 */
function withBanner(body: string, style: BannerStyle): string {
  const block = `${banner(style)}\n`;
  const fence = /^---\n[\s\S]*?\n---\n/.exec(body);
  const draft = fence
    ? body.slice(0, fence[0].length) + "\n" + block + body.slice(fence[0].length)
    : block + body;
  // The hash covers the whole file (with a placeholder in its own slot), so any
  // later hand edit is detectable by `ownershipOf`.
  return draft.replace(HASH_PLACEHOLDER, hashOf(draft));
}

function banner(style: BannerStyle): string {
  const lines = [...BANNER_LINES, `map-sha256: ${HASH_PLACEHOLDER}`];
  if (style === "hash") {
    return lines.map((line) => `# ${line}`).join("\n");
  }
  return `<!--\n${lines.map((line) => `  ${line}`).join("\n")}\n-->`;
}
